using System;using System.IO;using System.Linq;using System.Reflection;using System.Windows.Forms;using Musikbox;using MusikboxTests;
class FileUndoUi57Tests {static object Call(object o,string n,params object[] a){return o.GetType().GetMethod(n,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(o,a);}[STAThread]static void Main(string[] args){string path=Path.GetFullPath("verify/undo-ui.mp3");File.Copy(args[0],path,true);var song=MediaMetadata.Read(path);string before=TagFields.Read(path)["track"];using(var v=new MainView(Path.GetFullPath("verify/undo-layout.json"))){var c=new Controller(v,Path.GetFullPath("verify/undo-backups"),new Playback(new PlaybackTestDevice()));var p=new Project();p.Folders.Add(new BoxFolder{Name="Test",Theme="Test",Songs=new System.Collections.Generic.List<Song>{song}});Call(c,"ReplaceProject",p,null,true);v.Show();v.Songs.Rows[0].Selected=true;v.Songs.CurrentCell=v.Songs.Rows[0].Cells[0];Call(c,"SaveFileChanges",TrackNumbering.Plan(new[]{song},7,true,true,false),"Test");if(TagFields.Read(path)["track"]!="07/1")throw new Exception("Save");v.InvokeCommand("Rückgängig");if(TagFields.Read(path)["track"]!=before)throw new Exception("Undo");v.InvokeCommand("Wiederholen");if(TagFields.Read(path)["track"]!="07/1")throw new Exception("Redo");v.InvokeCommand("Rückgängig");if(TagFields.Read(path)["track"]!=before)throw new Exception("Final undo");typeof(Controller).GetField("dirty",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(c,false);v.Close();}Console.WriteLine("BESTANDEN: 4 Dateischreib-/Undo-/Redo-Prüfungen über echte Studio-Befehle");}}
